   const r=await p.connect();
   generation.current++;aiId.current++;worker.current?.terminate();worker.current=null;setAiText('');setAiState('idle');setAiStatus('');setSim(null);setModal(false);setProvider(p);setWalletName(choice.name);setWallet(r.publicKey.toBase58());
